SELECT fp.code AS period, SUM(CASE WHEN a.account_class = 'REVENUE' THEN jl.credit-jl.debit ELSE 0 END) AS revenue, SUM(CASE WHEN a.account_class IN ('EXPENSE','OTHER_EXPENSE') THEN jl.debit-jl.credit ELSE 0 END) AS expense FROM journal_line jl JOIN journal_entry je ON je.id=jl.entry_id JOIN fiscal_period fp ON fp.id=je.period_id JOIN account a ON a.id=jl.account_id WHERE je.state='POSTED' GROUP BY fp.code ORDER BY fp.code;
